examples.code:
const user = {
  name: 'Динара',
  role: 'admin',
  'login count': 42,   // ключ с пробелом — только через скобки
};

const key = 'role';

document.body.append(user.name + ' | ' + user[key] + ' | ' + user['login count']);

const settings = { theme: 'dark', fontSize: 14, lang: 'ru' };

const { theme, fontSize } = settings;

let line = theme + '/' + fontSize + ': ';
for (const [key, value] of Object.entries(settings)) {
  line += key + '=' + value + ' ';
}

document.body.append(line);

const order = { id: 7, items: ['чай', 'мёд'], paid: true };

const text = JSON.stringify(order); // строка — в таком виде данные уходят на сервер
const copy = JSON.parse(text);      // снова объект

document.body.append(text + ' | ' + copy.items[0] + ' | ' + (copy === order));

